1	package org.springframework.samples.petclinic.rest.function.common;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives the owner's {@code identityKey}, the single value all create-owner duplicate detection is
7	 * based on.
8	 *
9	 * <p>The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)},
10	 * built from values that are already in their canonical form by the time they reach here — the
11	 * telephone normalized to E.164 and the email lower-cased. A create is rejected with 409 Conflict
12	 * only when a new owner's <em>whole</em> key equals an existing owner's; because the telephone is
13	 * part of the key, two members of the same household (same {@code householdId}) with different
14	 * telephones have different keys and are both allowed.
15	 */
16	public final class IdentityKeys {
17	
18	    private IdentityKeys() {
19	    }
20	
21	    /** The identity key of a persisted owner, from its stored telephone, email and household id. */
22	    public static String of(Owner owner) {
23	        return of(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
24	    }
25	
26	    /** The identity key for the given components; a {@code null} component contributes an empty part. */
27	    public static String of(String telephone, String email, String householdId) {
28	        return safe(telephone) + "|" + safe(email) + "|" + safe(householdId);
29	    }
30	
31	    private static String safe(String value) {
32	        return value == null ? "" : value;
33	    }
34	}
