1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	import org.springframework.samples.petclinic.rest.function.common.IdentityKeys;
9	
10	/**
11	 * The duplicate-detection step of {@code POST /api/owners}. Runs after {@link ValidateOwnerFields}
12	 * has normalized the telephone and email. It computes the request's deterministic
13	 * {@code householdId} from its last name and postcode (see {@link Households#householdId}) and
14	 * rejects the create with a 409 Conflict in two cases:
15	 *
16	 * <ul>
17	 * <li><b>Identity duplicate</b> — the request's whole {@code identityKey}
18	 * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) equals an existing
19	 * owner's. This always rejects, even when {@code sharesHousehold} is set.</li>
20	 * <li><b>Household duplicate</b> — an existing owner already occupies the same household (same
21	 * computed {@code householdId}, i.e. same last name and postcode). This rejects <em>unless</em> the
22	 * request opts in with {@code sharesHousehold: true}, in which case the owner is created as a
23	 * declared household member.</li>
24	 * </ul>
25	 *
26	 * <p>{@code sharesHousehold} therefore only bypasses the household-duplicate block; it never lets a
27	 * full identity duplicate through.
28	 */
29	public class RejectDuplicateIdentity {
30	
31	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
32	            throws DuplicateIdentityException {
33	        String householdId = Households.householdId(request.getLastName(), request.getPostcode());
34	        String identityKey = IdentityKeys.of(request.getTelephone(), request.getEmail(), householdId);
35	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
36	        for (Owner existing : ownerRepository.findAll()) {
37	            if (existing.isDeleted()) {
38	                // A soft-deleted owner is no longer a live identity; it cannot block a create.
39	                continue;
40	            }
41	            if (identityKey.equals(IdentityKeys.of(existing))) {
42	                throw new DuplicateIdentityException(identityKey);
43	            }
44	            if (!sharesHousehold && householdId.equals(householdIdOf(existing))) {
45	                throw new DuplicateIdentityException(householdId);
46	            }
47	        }
48	    }
49	
50	    /** The household an existing owner belongs to, computed from its last name and postcode. */
51	    private static String householdIdOf(Owner existing) {
52	        return Households.householdId(existing.getLastName(), existing.getPostcode());
53	    }
54	}
