1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Step of {@code POST /api/owners} that runs after {@link BuildOwner} has produced the owner and
8	 * stamps its {@code householdId}. The id is derived deterministically from the owner's last name and
9	 * postcode (see {@link Households#householdId}), so every owner with the same last name and postcode
10	 * gets the same value automatically — the household needs no linking step and there is nothing to
11	 * back-fill.
12	 *
13	 * <p>Unlike the earlier behaviour, this is unconditional: {@code sharesHousehold} no longer creates
14	 * the household link (it only bypasses the household-duplicate block in {@link RejectDuplicateIdentity})
15	 * and even a lone owner carries the computed id. Downstream steps that key off the household —
16	 * {@link AssignHouseholdSize} and duplicate detection — read this same computed value.
17	 */
18	public class AssignHousehold {
19	
20	    public void service(@Val Owner owner) {
21	        owner.setHouseholdId(Households.householdId(owner.getLastName(), owner.getPostcode()));
22	    }
23	}
