1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Canonical household logic shared by the create-owner pipeline. A household is keyed on
10	 * {@code (lastName, postcode)}: every owner with the same last name (compared case-insensitively
11	 * with collapsed whitespace) and the same postcode belongs to the same household and so resolves to
12	 * the same deterministic {@code householdId}. {@link RejectDuplicateIdentity} uses this to detect
13	 * household duplicates and to fold the household component into a request's identity key, and
14	 * {@link AssignHousehold} uses it to stamp the computed id onto the owner, so both compute the same
15	 * value.
16	 */
17	final class Households {
18	
19	    private Households() {
20	    }
21	
22	    /**
23	     * The deterministic {@code householdId} for the given last name and postcode: the first 12 hex
24	     * characters of {@code SHA-256(normalizedLastName + '|' + postcode)}. It is computed for every
25	     * owner regardless of {@code sharesHousehold}, so owners with the same last name and postcode
26	     * share it automatically. Never {@code null}.
27	     */
28	    static String householdId(String lastName, String postcode) {
29	        String key = normalizeName(lastName) + "|" + normalizePostcode(postcode);
30	        try {
31	            byte[] digest = MessageDigest.getInstance("SHA-256")
32	                    .digest(key.getBytes(StandardCharsets.UTF_8));
33	            StringBuilder sb = new StringBuilder();
34	            for (int i = 0; i < 6; i++) {
35	                sb.append(String.format("%02x", digest[i]));
36	            }
37	            return sb.toString();
38	        }
39	        catch (NoSuchAlgorithmException ex) {
40	            throw new IllegalStateException("SHA-256 not available", ex);
41	        }
42	    }
43	
44	    /** Lower-case, trim and collapse internal whitespace runs to a single space. */
45	    static String normalizeName(String value) {
46	        if (value == null) {
47	            return "";
48	        }
49	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
50	    }
51	
52	    /** Trim the postcode; a {@code null} value contributes the empty string. */
53	    static String normalizePostcode(String value) {
54	        return value == null ? "" : value.trim();
55	    }
56	}
