1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Soft-match step of {@code POST /api/owners}. By the time it runs the request has already passed
10	 * {@link RejectDuplicateIdentity}, so it is <em>not</em> a hard duplicate; this step then looks for a
11	 * weaker signal that it might be one anyway: an existing owner that shares this owner's
12	 * {@code lastName} (compared case-insensitively) and {@code postcode} but has a <em>different</em>
13	 * telephone. Such an owner is still created, but is flagged with {@code possibleDuplicate = true} and
14	 * {@code possibleDuplicateOf} set to the matching owner's id (the lowest id when several match).
15	 * When nothing matches, {@code possibleDuplicate} is set to {@code false} and no id is recorded.
16	 *
17	 * <p>A <em>declared</em> household member — one created with {@code sharesHousehold: true} — is never
18	 * flagged: it already reached this step by opting past the household-duplicate block in
19	 * {@link RejectDuplicateIdentity}, so sharing a same-household owner's lastName and postcode is
20	 * expected, not a suspected duplicate.
21	 *
22	 * <p>Runs after {@link BuildOwner} so the owner carries its normalized lastName, postcode and
23	 * telephone, and before {@link SaveOwner} so the comparison sees only owners that existed before this
24	 * create — the new owner is not yet persisted and so never matches itself. {@code @Val} yields the
25	 * built owner, mutated in place and persisted by the save step.
26	 */
27	public class AssignPossibleDuplicate {
28	
29	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
30	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
31	            // A declared household member is not a suspected duplicate.
32	            owner.setPossibleDuplicate(false);
33	            owner.setPossibleDuplicateOf(null);
34	            return;
35	        }
36	        String lastName = Households.normalizeName(owner.getLastName());
37	        String postcode = normalizePostcode(owner.getPostcode());
38	        String telephone = owner.getTelephone();
39	        Integer match = null;
40	        if (postcode != null) {
41	            for (Owner existing : ownerRepository.findAll()) {
42	                if (existing.isDeleted()) {
43	                    // A soft-deleted owner is not a live duplicate to flag against.
44	                    continue;
45	                }
46	                if (lastName.equals(Households.normalizeName(existing.getLastName()))
47	                        && postcode.equals(normalizePostcode(existing.getPostcode()))
48	                        && !equalsSafely(telephone, existing.getTelephone())
49	                        && existing.getId() != null
50	                        && (match == null || existing.getId() < match)) {
51	                    match = existing.getId();
52	                }
53	            }
54	        }
55	        owner.setPossibleDuplicate(match != null);
56	        owner.setPossibleDuplicateOf(match);
57	    }
58	
59	    /** Trim the postcode, treating a null or blank value as absent (no possible-duplicate match). */
60	    private static String normalizePostcode(String value) {
61	        if (value == null) {
62	            return null;
63	        }
64	        String trimmed = value.trim();
65	        return trimmed.isEmpty() ? null : trimmed;
66	    }
67	
68	    private static boolean equalsSafely(String a, String b) {
69	        return a == null ? b == null : a.equals(b);
70	    }
71	}
