1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import jakarta.validation.ConstraintViolation;
7	import jakarta.validation.Validator;
8	import net.officefloor.plugin.variable.Out;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
11	import org.springframework.samples.petclinic.rest.function.common.Postcodes;
12	import org.springframework.web.bind.annotation.RequestBody;
13	
14	/**
15	 * First step of {@code POST /api/owners}. Rejects a body that is missing (absent) or blank
16	 * (whitespace only) in any of firstName, lastName, address, city or telephone — {@code @Size(min = 1)}
17	 * on the DTO does not catch a whitespace-only value, so the check is explicit here. The remaining
18	 * schema constraints (pattern, max length) are validated too, so a bad value is still a 400.
19	 *
20	 * <p>Binds the body directly (no {@code @Valid}) so that a missing field surfaces as this rule's
21	 * {@code errors} response rather than the generic schema-validation escalation, and publishes the
22	 * body for {@link BuildOwner} to consume.
23	 */
24	public class ValidateOwnerFields {
25	
26	    public void service(@RequestBody OwnerFieldsDto request, Validator validator, Out<OwnerFieldsDto> validated)
27	            throws MissingOwnerFieldsException {
28	        List<String> errors = new ArrayList<>();
29	        normalizeAddress(request);
30	        addIfBlank(errors, "firstName", request.getFirstName());
31	        addIfBlank(errors, "lastName", request.getLastName());
32	        addIfBlank(errors, "address", request.getAddress());
33	        addIfBlank(errors, "city", request.getCity());
34	        normalizeTelephone(errors, request);
35	        for (ConstraintViolation<OwnerFieldsDto> violation : validator.validate(request)) {
36	            String field = violation.getPropertyPath().toString();
37	            if (!field.isEmpty() && !errors.contains(field)) {
38	                errors.add(field);
39	            }
40	        }
41	        validatePostcode(errors, request);
42	        if (!errors.isEmpty()) {
43	            throw new MissingOwnerFieldsException(errors);
44	        }
45	        normalizeEmail(request);
46	        validated.set(request);
47	    }
48	
49	    /**
50	     * Email is optional. When absent nothing is done; when present the schema {@code @Email}
51	     * constraint (checked above) has already rejected a syntactically invalid address with a
52	     * {@code 400}, so a value reaching here is valid and is stored and returned lower-cased.
53	     */
54	    private static void normalizeEmail(OwnerFieldsDto request) {
55	        String email = request.getEmail();
56	        if (email != null) {
57	            request.setEmail(email.toLowerCase(java.util.Locale.ROOT));
58	        }
59	    }
60	
61	    /**
62	     * Canonically normalize the address (trim, collapse whitespace, upper-case, expand common
63	     * abbreviations) and write it back onto the request so it is stored and returned in normalized
64	     * form. The structured form is preferred: when {@code addressLine1} normalizes to a non-blank
65	     * value the structured lines are normalized and the flat {@code address} is set to the composed
66	     * value — the normalized {@code addressLine1} with a single space and the normalized
67	     * {@code addressLine2} appended when {@code addressLine2} is present. Otherwise the flat
68	     * {@code address} input is normalized and the structured lines are cleared, keeping earlier
69	     * flat-only owners backward compatible. Running before the blank check means an owner that
70	     * supplies neither form — and so has a blank composed {@code address} — is rejected as an
71	     * {@code address} required-field error (400).
72	     */
73	    private static void normalizeAddress(OwnerFieldsDto request) {
74	        String line1 = AddressNormalizer.normalize(request.getAddressLine1());
75	        if (!line1.isEmpty()) {
76	            String line2 = AddressNormalizer.normalize(request.getAddressLine2());
77	            request.setAddressLine1(line1);
78	            if (line2.isEmpty()) {
79	                request.setAddressLine2(null);
80	                request.setAddress(line1);
81	            }
82	            else {
83	                request.setAddressLine2(line2);
84	                request.setAddress(line1 + " " + line2);
85	            }
86	        }
87	        else {
88	            request.setAddressLine1(null);
89	            request.setAddressLine2(null);
90	            request.setAddress(AddressNormalizer.normalize(request.getAddress()));
91	        }
92	    }
93	
94	    /**
95	     * Postcode is optional and validated only when present. Its 4-digit format is enforced by the
96	     * schema {@code @Pattern} (checked above, so a malformed value is already a {@code postcode}
97	     * error). When it is well-formed it must also be in range for the region derived from the
98	     * owner's city (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region
99	     * accepts any 4-digit postcode. An out-of-range postcode is a {@code postcode} error (400).
100	     */
101	    private static void validatePostcode(List<String> errors, OwnerFieldsDto request) {
102	        String postcode = request.getPostcode();
103	        if (postcode != null && !errors.contains("postcode")
104	                && !Postcodes.isValidForCity(postcode, request.getCity())) {
105	            errors.add("postcode");
106	        }
107	    }
108	
109	    private static void addIfBlank(List<String> errors, String name, String value) {
110	        if (value == null || value.isBlank()) {
111	            errors.add(name);
112	        }
113	    }
114	
115	    /**
116	     * Normalize the telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
117	     * '+' with country code is kept as-is; otherwise the number is assumed to be Australian ('+61')
118	     * and a single leading '0' is dropped from the national digits. The result must have 8 to 15
119	     * digits after the '+'. The E.164 value is written back onto the request so it is stored and
120	     * returned as {@code telephone}. Anything that cannot form a valid E.164 number is a
121	     * {@code telephone} error (400).
122	     */
123	    private static void normalizeTelephone(List<String> errors, OwnerFieldsDto request) {
124	        String e164 = toE164(request.getTelephone());
125	        if (e164 == null) {
126	            errors.add("telephone");
127	            return;
128	        }
129	        request.setTelephone(e164);
130	    }
131	
132	    /**
133	     * Country codes with a fixed national-number length. When a number's country code appears here
134	     * its national digits (everything after the code) must match exactly, otherwise it is rejected;
135	     * country codes not listed fall back to the generic 8–15 total-digit rule. '+61' (Australia)
136	     * requires 9 national digits, '+1' (NANP) requires 10.
137	     */
138	    private static final java.util.Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY =
139	            java.util.Map.of("61", 9, "1", 10);
140	
141	    /**
142	     * Convert a raw telephone into E.164 form, or return {@code null} when it cannot form a valid
143	     * E.164 number (fewer than 8 or more than 15 digits after the '+', a national-number length that
144	     * is wrong for its country code, or stray non-digit characters remaining after the allowed
145	     * separators are stripped).
146	     */
147	    static String toE164(String value) {
148	        if (value == null) {
149	            return null;
150	        }
151	        String cleaned = value.replaceAll("[\\s()-]", "");
152	        String digits;
153	        if (cleaned.startsWith("+")) {
154	            digits = cleaned.substring(1);
155	        }
156	        else {
157	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
158	            digits = "61" + national;
159	        }
160	        if (!digits.matches("[0-9]{8,15}")) {
161	            return null;
162	        }
163	        if (!hasValidNationalLength(digits)) {
164	            return null;
165	        }
166	        return "+" + digits;
167	    }
168	
169	    /**
170	     * For a country code with a fixed national-number length, check the national digits (everything
171	     * after the code) match that length exactly. Unknown country codes pass (already bounded by the
172	     * generic 8–15 total-digit rule).
173	     */
174	    private static boolean hasValidNationalLength(String digits) {
175	        for (java.util.Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY.entrySet()) {
176	            String code = entry.getKey();
177	            if (digits.startsWith(code)) {
178	                return digits.length() - code.length() == entry.getValue();
179	            }
180	        }
181	        return true;
182	    }
183	}
