3	import java.util.Locale;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;
9	
10	/**
11	 * Step of {@code POST /api/owners} that runs after {@link ValidateOwnerFields} has published the
12	 * request (with the email already normalized to lower case). Rejects the request when the email's
13	 * domain is on the disposable-domain blocklist, so a throwaway address is a 400 Bad Request rather
14	 * than a create. Email is optional; an absent or domain-less value is left for the other rules.
15	 */
16	public class RejectDisposableEmailDomain {
17	
18	    /** Domains for throwaway email providers that are not accepted. */
19	    static final Set<String> BLOCKED_DOMAINS =
20	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
21	
22	    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
23	        String email = request.getEmail();
24	        if (email == null) {
25	            return;
26	        }
27	        int at = email.lastIndexOf('@');
28	        if (at < 0) {
29	            return;
30	        }
31	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
32	        if (BLOCKED_DOMAINS.contains(domain)) {
33	            throw new DisposableEmailDomainException(domain);
34	        }
35	    }
36	}
